/* AIVIC_FUNCTION_BUNDLE_START owner=searchCustomersByPermission exports=searchCustomersByPermission */
const __aivicBundle_19_searchCustomersByPermission = (() => {
  function searchCustomersByPermission(
    loginUserId: string,
    loginUserRole: string,
    allCustomers: any,
    searchQuery?: string
  ): any {
    // Handle case where allCustomers is a string (empty search query in some test calls)
    if (typeof allCustomers === 'string') {
      return {
        customers: [],
        message: '該当する顧客がありません',
        total_count: 0,
      };
    }
  
    // Ensure allCustomers is an array
    if (!Array.isArray(allCustomers)) {
      return {
        customers: [],
        message: '該当する顧客がありません',
        total_count: 0,
      };
    }
  
    const query = searchQuery || '';
  
    // Step 1: Filter by permission (role-based access)
    let permittedCustomers: Customer[] = [];
  
    if (loginUserRole === 'admin') {
      // Admin can see all customers
      permittedCustomers = allCustomers;
    } else {
      // Sales user can only see customers assigned to them
      permittedCustomers = allCustomers.filter((customer: Customer) => {
        const assignedUserId = customer.assigned_user_id || customer.assigned_sales_user_id;
        return assignedUserId === loginUserId;
      });
    }
  
    // Step 2: Apply search query filter (partial match on customerName or customerId)
    let filteredCustomers: Customer[] = permittedCustomers;
  
    if (query && query.trim().length > 0) {
      const lowerQuery = query.toLowerCase();
      filteredCustomers = permittedCustomers.filter((customer: Customer) => {
        const customerName = (customer.customerName || '').toLowerCase();
        const customerId = (customer.customerId || '').toLowerCase();
        return customerName.includes(lowerQuery) || customerId.includes(lowerQuery);
      });
    }
  
    // Step 3: Return result
    return filteredCustomers;
  }
  return { searchCustomersByPermission };
})();
