/* AIVIC_FUNCTION_BUNDLE_START owner=searchCustomersWithPermission exports=searchCustomersWithPermission */
const __aivicBundle_20_searchCustomersWithPermission = (() => {
  function searchCustomersWithPermission(
    customersInSystem: Customer[],
    userId: string,
    searchQuery: string,
  ): Customer[] {
    // Step 1: Filter customers assigned to the specified userId
    const assignedCustomers = customersInSystem.filter(
      (customer) =>
        customer.assigned_sales_user_id === userId ||
        customer.assigned_user_id === userId,
    );
  
    // Step 2: If searchQuery is empty, return all assigned customers
    if (!searchQuery || searchQuery.trim() === '') {
      return assignedCustomers;
    }
  
    // Step 3: Filter by partial match on customer name or customer ID
    const lowerQuery = searchQuery.toLowerCase();
    return assignedCustomers.filter((customer) => {
      const customerName = (customer.customerName || '')
        .toLowerCase();
      const customerId = (customer.customerId || '')
        .toLowerCase();
  
      return (
        customerName.includes(lowerQuery) || customerId.includes(lowerQuery)
      );
    });
  }
  return { searchCustomersWithPermission };
})();
