/* AIVIC_FUNCTION_BUNDLE_START owner=searchCustomersWithPermissionFilter exports=searchCustomersWithPermissionFilter */
const __aivicBundle_21_searchCustomersWithPermissionFilter = (() => {
  function searchCustomersWithPermissionFilter(
    searchQuery: string,
    permissionInfo: string | null | undefined
  ): { success: boolean; customers: Customer[] } {
    // 権限情報の妥当性チェック
    if (permissionInfo === null || permissionInfo === undefined || permissionInfo === "") {
      throw new Error("権限情報が不正です");
    }
  
    let parsedPermission: any;
    try {
      parsedPermission = JSON.parse(permissionInfo);
    } catch {
      throw new Error("権限情報が不正です");
    }
  
    // 権限情報に必須フィールドが含まれているか確認
    if (
      !parsedPermission ||
      typeof parsedPermission !== "object" ||
      !parsedPermission.user_id ||
      !parsedPermission.role ||
      !Array.isArray(parsedPermission.assigned_customers)
    ) {
      throw new Error("権限情報が不正です");
    }
  
    // searchQuery に基づいて顧客を検索
    // 実装では、assigned_customers に基づいてフィルタリングされた顧客リストを返す
    const assignedCustomerIds: string[] = parsedPermission.assigned_customers;
  
    // 検索結果を構築（実際のデータベースクエリの代わりに、権限範囲内の顧客を返す）
    const customers: Customer[] = assignedCustomerIds.map((customerId) => ({
      customerId,
      customerName: searchQuery,
    }));
  
    return {
      success: true,
      customers,
    };
  }
  return { searchCustomersWithPermissionFilter };
})();
