/* AIVIC_FUNCTION_BUNDLE_START owner=filterPurchaseHistoryByDuration exports=filterPurchaseHistoryByDuration */
const __aivicBundle_22_filterPurchaseHistoryByDuration = (() => {
  function filterPurchaseHistoryByDuration(params: {
    purchase_history: PurchaseRecord[];
    reference_date: string;
    duration_years: number;
  }): FilteredPurchaseResult {
    const { purchase_history, reference_date, duration_years } = params;
  
    const referenceDateTime = new Date(reference_date).getTime();
    const durationMs = duration_years * 365.25 * 24 * 60 * 60 * 1000;
    const cutoffTime = referenceDateTime - durationMs;
  
    const filtered_records: PurchaseRecord[] = [];
    let excluded_count = 0;
    let total_amount_within_duration = 0;
  
    for (const record of purchase_history) {
      const purchaseDateStr = record.purchase_date || record.purchaseDate;
      const purchaseDateTime = new Date(purchaseDateStr as string).getTime();
  
      if (purchaseDateTime >= cutoffTime) {
        filtered_records.push(record);
        total_amount_within_duration += record.amount;
      } else {
        excluded_count++;
      }
    }
  
    return {
      filtered_records,
      excluded_count,
      total_amount_within_duration,
      is_filtered: true,
      filter_criteria: {
        duration_years,
        reference_date,
      },
    };
  }
  return { filterPurchaseHistoryByDuration };
})();
